def write_tr():
    for k, l in enumerate(('fr', 'de', 'it')):
        p = ROOT / f'tools/i18n/{l}.json'; d = json.load(open(p))
        for en, tr in TR.items(): d[en] = tr[k]
        json.dump(d, open(p, 'w'), ensure_ascii=False, indent=0)
